def choice_confidence(probabilities: dict[str, float]) -> float:
    n = len(probabilities)
    return (max(probabilities.values()) - 1 / n) / (1 - 1 / n)

GATES = {
    "assign_team": {"act": 0.70, "confirm": 0.40},
    "auto_close_duplicate": {"act": 0.95, "confirm": 0.60},
}

def band(action: str, confidence: float) -> str:
    g = GATES[action]
    if confidence >= g["act"]:
        return "auto"
    if confidence >= g["confirm"]:
        return "confirm"
    return "human"

FIRE_T = 0.7

def should_escalate(checks: dict[str, float]) -> tuple[bool, dict[str, float]]:
    fired = {qid: p for qid, p in checks.items() if p > FIRE_T}
    return bool(fired), fired
